-- SYNTHETIC fixture (not customer data). Mimics DBMS_METADATA.GET_DDL output style:
-- quoted identifiers, owner prefixes, storage clauses, USING INDEX, separate key indexes,
-- identity options, NOVALIDATE/DEFERRABLE states, comments and a sequence.
SET DEFINE OFF
PROMPT synthetic schema for WP9.3 converter regression

  CREATE TABLE "SYN_OWNER"."SYN_CUSTOMERS"
   (	"CUSTOMER_ID" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 100 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"CUSTOMER_CODE" VARCHAR2(20 CHAR) CONSTRAINT "SYN_CUSTOMERS_CODE_NN" NOT NULL ENABLE,
	"EMAIL" VARCHAR2(320 BYTE),
	"CREDIT_LIMIT" NUMBER(12,2) DEFAULT 0 NOT NULL ENABLE,
	"STATUS" CHAR(1 CHAR) DEFAULT ON NULL 'A',
	"CREATED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT SYSTIMESTAMP,
	 CONSTRAINT "SYN_CUSTOMERS_PK" PRIMARY KEY ("CUSTOMER_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "USERS"  ENABLE,
	 CONSTRAINT "SYN_CUSTOMERS_UK1" UNIQUE ("CUSTOMER_CODE")
  USING INDEX TABLESPACE "USERS"  ENABLE,
	 CONSTRAINT "SYN_CUSTOMERS_CK1" CHECK (status in ('A', 'I')) ENABLE,
	 CONSTRAINT "SYN_CUSTOMERS_CK2" CHECK (credit_limit between 0 and 1000000) ENABLE NOVALIDATE,
	 CONSTRAINT "SYN_CUSTOMERS_CK3" CHECK (regexp_like(email, '^[^@]+@[^@]+$')) ENABLE
   ) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  TABLESPACE "USERS" ;

  CREATE UNIQUE INDEX "SYN_OWNER"."SYN_CUSTOMERS_PK" ON "SYN_OWNER"."SYN_CUSTOMERS" ("CUSTOMER_ID")
  PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS TABLESPACE "USERS" ;

  CREATE INDEX "SYN_OWNER"."SYN_CUSTOMERS_EMAIL_FI" ON "SYN_OWNER"."SYN_CUSTOMERS" (UPPER("EMAIL"))
  TABLESPACE "USERS" ;

  CREATE INDEX "SYN_OWNER"."SYN_CUSTOMERS_TOCHAR_FI" ON "SYN_OWNER"."SYN_CUSTOMERS" (TO_CHAR("CREATED_AT", 'YYYY'));

  CREATE TABLE "SYN_OWNER"."SYN_ORDERS"
   (	"ORDER_ID" NUMBER(18,0) GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL ENABLE,
	"CUSTOMER_ID" NUMBER CONSTRAINT "SYN_ORDERS_CUST_FK" REFERENCES "SYN_OWNER"."SYN_CUSTOMERS" ON DELETE SET NULL,
	"ORDER_DATE" DATE DEFAULT TRUNC(SYSDATE) NOT NULL ENABLE,
	"QTY" NUMBER(9,0) NOT NULL ENABLE,
	"PRICE" NUMBER(12,2) NOT NULL ENABLE,
	"TOTAL" NUMBER(14,2) GENERATED ALWAYS AS (ROUND("QTY"*"PRICE",2)) VIRTUAL,
	"NOTE" CLOB,
	"CREATED_BY" VARCHAR2(255) DEFAULT SYS_CONTEXT('APEX$SESSION','APP_USER'),
	 CONSTRAINT "SYN_ORDERS_PK" PRIMARY KEY ("ORDER_ID") DEFERRABLE INITIALLY DEFERRED ENABLE,
	 CONSTRAINT "SYN_ORDERS_CK1" CHECK ("QTY" > 0) DISABLE
   ) TABLESPACE "USERS" ;

ALTER TABLE "SYN_OWNER"."SYN_ORDERS" ADD CONSTRAINT "SYN_ORDERS_CUST2_FK" FOREIGN KEY ("CUSTOMER_ID")
	  REFERENCES "SYN_OWNER"."SYN_CUSTOMERS" ("CUSTOMER_ID") ENABLE NOVALIDATE;

  CREATE TABLE "SYN_OWNER"."SYN_DOCS"
   (	"DOC_ID" NUMBER(10,0) NOT NULL ENABLE,
	"PAYLOAD" XMLTYPE,
	 CONSTRAINT "SYN_DOCS_PK" PRIMARY KEY ("DOC_ID") ENABLE
   ) ;

  CREATE TABLE "SYN_OWNER"."SYN_DOC_LINKS"
   (	"DOC_ID" NUMBER(10,0) NOT NULL ENABLE,
	"ORDER_ID" NUMBER(18,0) NOT NULL ENABLE,
	 CONSTRAINT "SYN_DOC_LINKS_FK1" FOREIGN KEY ("DOC_ID") REFERENCES "SYN_OWNER"."SYN_DOCS" ("DOC_ID") ENABLE,
	 CONSTRAINT "SYN_DOC_LINKS_FK2" FOREIGN KEY ("ORDER_ID") REFERENCES "SYN_OWNER"."SYN_ORDERS" ("ORDER_ID") ENABLE
   ) ;

  CREATE SEQUENCE  "SYN_OWNER"."SYN_BATCH_SEQ"  MINVALUE 1 MAXVALUE 999999999 INCREMENT BY 1 START WITH 21 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  GLOBAL ;

   COMMENT ON TABLE "SYN_OWNER"."SYN_CUSTOMERS"  IS 'Customer master (synthetic)';
   COMMENT ON COLUMN "SYN_OWNER"."SYN_CUSTOMERS"."CREDIT_LIMIT" IS 'Limit in IDR; can''t be negative';

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SYN_OWNER"."SYN_ORDER_TOTALS_V" ("CUSTOMER_CODE", "ORDER_COUNT", "TOTAL_VALUE") AS
  select c.customer_code, count(o.order_id), nvl(sum(o.total), 0)
    from "SYN_OWNER"."SYN_CUSTOMERS" c
    left join syn_orders o on o.customer_id = c.customer_id
   group by c.customer_code;

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SYN_OWNER"."SYN_RECENT_V" AS
  select order_id, decode(qty, 0, 'NONE', 'SOME') qty_flag from syn_orders where rownum <= 10;

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SYN_OWNER"."SYN_ACTIVE_CUSTOMERS_V" AS
  select customer_id, customer_code from syn_customers where status = 'A'
  minus
  select customer_id, customer_code from syn_customers where credit_limit = 0
  with read only;

insert into syn_customers (customer_code) values ('C-1');
commit;
